<script setup lang="ts">
import{computed,onMounted,ref}from'vue';
const props=defineProps<{load:()=>Promise<any>;send:(input:Record<string,unknown>)=>Promise<any>;initial?:any;language?:string}>();
const tr=(id:string,en:string)=>props.language==='en'?en:id;
const data=ref<any>(props.initial??null),busy=ref(false),error=ref(''),notice=ref(''),panel=ref('orders'),receipt=ref<any>(null),selected=ref<any>(null),payment=ref(''),shiftCash=ref(''),billingPeriod=ref('');
const resource=ref({name:'',unit:'kg',rate:'',enabled:true});const form=ref({resource_id:'',customer_name:'',contact:'',start_date:new Date().toISOString().slice(0,10),end_date:new Date().toISOString().slice(0,10),quantity:'1'});
const type=computed(()=>data.value?.type??'laundry');const laundry=computed(()=>type.value==='laundry');const title=computed(()=>laundry.value?'Laundry':type.value==='boarding'?tr('Kosan','Boarding house'):'Homestay');
const statusNames:Record<string,[string,string]>={received:['Diterima','Received'],washing:['Dicuci','Washing'],drying:['Dikeringkan','Drying'],ironing:['Disetrika','Ironing'],ready:['Siap diambil','Ready'],collected:['Diambil','Collected'],reserved:['Dipesan','Reserved'],checked_in:['Dihuni','Checked in'],checked_out:['Selesai','Checked out'],cancelled:['Dibatalkan','Cancelled']};
const states=computed(()=>laundry.value?['received','washing','drying','ironing','ready','collected']:['reserved','checked_in','checked_out']);const nextState=(s:string)=>states.value[states.value.indexOf(s)+1];
const money=(v:number)=>`${data.value?.symbol??data.value?.currency??''} ${new Intl.NumberFormat(props.language==='en'?'en-US':'id-ID',{minimumFractionDigits:data.value?.scale??0,maximumFractionDigits:data.value?.scale??0}).format(Number(v)/10**(data.value?.scale??0))}`;
function numeric(raw:string,scale:number){if(!new RegExp(`^\\d+(?:[.,]\\d{1,${Math.max(1,scale)}})?$`).test(raw)||scale===0&&/[.,]/.test(raw))throw Error('INVALID_NUMERIC_VALUE');const [w,f='']=raw.replace(',','.').split('.');const v=Number(w)*10**scale+Number(f.padEnd(scale,'0'));if(!Number.isSafeInteger(v)||v<0||v>100000000000)throw Error('INVALID_NUMERIC_VALUE');return v;}
const invoices=computed(()=>data.value?.invoices?.filter((i:any)=>i.order_id===selected.value?.id)??[]);
const active=computed(()=>data.value?.orders?.filter((o:any)=>!['collected','checked_out','cancelled'].includes(o.status)).length??0);
const due=computed(()=>data.value?.invoices?.reduce((n:number,i:any)=>n+Number(i.total_atomic)-Number(i.paid_atomic),0)??0);
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{data.value=await props.load();if(selected.value)selected.value=data.value.orders.find((o:any)=>o.id===selected.value.id)??null;}catch(e){error.value=tr('Data belum dapat dimuat. Periksa koneksi dan coba lagi.','Unable to load data. Check connection and retry.')+' · '+String(e);}finally{busy.value=false;}}
async function command(action:string,fields:Record<string,unknown>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const result=await props.send({action,operation_id:crypto.randomUUID(),...fields});if(result.queued){notice.value=tr('Tersimpan sebagai antrean lokal. Belum dikonfirmasi server; reservasi belum dijamin tersedia.','Saved to local queue. Not server-confirmed; reservations are not guaranteed.');return;}receipt.value=result.record;data.value=result.workspace??await props.load();if(selected.value)selected.value=data.value.orders.find((o:any)=>o.id===selected.value.id)??null;notice.value=tr('Berhasil disimpan dan dikonfirmasi server.','Saved and confirmed by the server.');if(action==='order.create'){form.value.customer_name='';form.value.contact='';}payment.value='';}catch(e){error.value=tr('Belum berhasil. Periksa status terbaru sebelum mengulangi.','Not completed. Check the latest state before retrying.')+' · '+String(e);}finally{busy.value=false;}}
function saveResource(){try{void command('resource.save',{id:'',version:0,name:resource.value.name,unit:laundry.value?resource.value.unit:type.value==='boarding'?'month':'night',rate_atomic:numeric(resource.value.rate,data.value.scale),currency:data.value.currency,scale:data.value.scale,enabled:true});}catch(e){error.value=String(e);}}
function create(){try{void command('order.create',{...form.value,quantity:undefined,quantity_milli:laundry.value?numeric(form.value.quantity,3):1000});}catch(e){error.value=String(e);}}
function pay(id:string){try{void command('payment.record',{invoice_id:id,amount_atomic:numeric(payment.value,data.value.scale)});}catch(e){error.value=String(e);}}
function shift(){try{void command(data.value.shift?'shift.close':'shift.open',{[data.value.shift?'closing_atomic':'opening_atomic']:numeric(shiftCash.value,data.value.scale)});}catch(e){error.value=String(e);}}
function print(){window.print();}
onMounted(()=>{if(!data.value)void refresh();});
</script>
<template><main class="service-workspace"><header class="service-head"><div><span class="service-eyebrow">{{data?.profile?.name??'oneQay'}} · {{tr('RUANG KERJA TERPISAH','ISOLATED WORKSPACE')}}</span><h1>{{title}}</h1><p>{{laundry?tr('Dari penerimaan cucian sampai pengambilan, setiap langkah tercatat.','Track every step from intake to collection.'):type==='boarding'?tr('Kelola kamar, penghuni, dan tagihan sewa berkala.','Manage rooms, residents and periodic rent.'):tr('Reservasi, ketersediaan kamar, check-in, dan check-out dalam satu alur.','Reservations, room availability, check-in and check-out in one workflow.')}}</p></div><button @click="refresh" :disabled="busy">↻ {{tr('Perbarui','Refresh')}}</button></header><p v-if="error" role="alert" class="service-error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status" aria-live="polite">{{tr('Memproses, mohon tunggu…','Processing, please wait…')}}</p><template v-if="data"><div class="service-kpis"><article><small>{{tr('Pesanan aktif pada daftar ini','Active orders on this page')}}</small><strong>{{active}}</strong></article><article><small>{{tr('Sisa tagihan pada daftar ini','Outstanding on this page')}}</small><strong>{{money(due)}}</strong></article><article><small>{{tr('Kasir','Register')}}</small><strong>{{data.shift?tr('Shift terbuka','Shift open'):tr('Belum dibuka','Not opened')}}</strong></article></div><nav class="service-tabs"><button v-for="(text,key) in {orders:tr('Operasional','Operations'),create:laundry?tr('Terima cucian','New laundry'):tr('Reservasi baru','New reservation'),resources:laundry?tr('Layanan & tarif','Services & rates'):tr('Kamar & tarif','Rooms & rates'),shift:tr('Buka / tutup kas','Open / close register')}" :key="key" @click="panel=key" :aria-current="panel===key?'page':undefined">{{text}}</button></nav>
<section v-if="panel==='orders'" class="service-panel"><h2>{{tr('Aktivitas terbaru','Recent activity')}}</h2><p v-if="!data.orders.length">{{tr('Belum ada pesanan. Mulai dari layanan atau kamar, lalu buat pesanan pertama.','No orders yet. Create a service or room, then add your first order.')}}</p><div class="service-table"><table v-if="data.orders.length"><thead><tr><th>{{tr('Pelanggan / penghuni','Customer / resident')}}</th><th>{{tr('Periode','Period')}}</th><th>Status</th><th>{{tr('Nilai','Amount')}}</th><th></th></tr></thead><tbody><tr v-for="o in data.orders" :key="o.id"><td>{{o.customer_name}}<small>{{data.resources.find((r:any)=>r.id===o.resource_id)?.name}}</small></td><td>{{o.start_date}} → {{o.end_date}}</td><td><span class="service-badge">{{statusNames[o.status]?.[language==='en'?1:0]??o.status}}</span></td><td>{{money(o.total_atomic)}}</td><td><button @click="selected=o">{{tr('Kelola','Manage')}}</button></td></tr></tbody></table></div></section>
<form v-if="panel==='create'" class="service-panel service-form" @submit.prevent="create"><h2>{{laundry?tr('Penerimaan cucian','Laundry intake'):tr('Reservasi kamar','Room reservation')}}</h2><label>{{laundry?tr('Layanan','Service'):tr('Kamar','Room')}}<select v-model="form.resource_id" required><option value="">{{tr('Pilih','Select')}}</option><option v-for="r in data.resources.filter((r:any)=>r.enabled)" :key="r.id" :value="r.id">{{r.name}} · {{money(r.rate_atomic)}} / {{r.unit}}</option></select></label><label>{{tr('Nama pelanggan / penghuni','Customer / resident name')}}<input v-model="form.customer_name" required maxlength="100"/></label><label>{{tr('Kontak','Contact')}}<input v-model="form.contact" type="tel" required maxlength="32"/></label><div class="service-grid"><label>{{laundry?tr('Tanggal diterima','Intake date'):tr('Mulai menginap','Arrival date')}}<input v-model="form.start_date" type="date" required/></label><label>{{laundry?tr('Estimasi selesai','Estimated completion'):tr('Tanggal akhir (tidak termasuk)','End date (exclusive)')}}<input v-model="form.end_date" type="date" :min="form.start_date" required/></label></div><label v-if="laundry">{{tr('Berat kg / jumlah potong','Weight kg / item count')}}<input v-model="form.quantity" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,3})?" required/></label><p>{{tr('Reservasi kamar diperiksa kembali oleh server saat disimpan. Tagihan kos berikutnya dibuat per periode dari detail kontrak.','Room availability is rechecked by the server when saving. Create subsequent boarding invoices by period in contract details.')}}</p><button class="service-primary" :disabled="busy">{{tr('Simpan pesanan','Save order')}}</button></form>
<section v-if="panel==='resources'" class="service-panel"><h2>{{laundry?tr('Layanan','Services'):tr('Kamar','Rooms')}}</h2><ul><li v-for="r in data.resources" :key="r.id">{{r.name}} · {{money(r.rate_atomic)}} / {{r.unit}}</li></ul><form v-if="data.can_configure" class="service-form" @submit.prevent="saveResource"><h3>{{tr('Tambah','Add')}}</h3><label>{{tr('Nama','Name')}}<input v-model="resource.name" required maxlength="100"/></label><label v-if="laundry">{{tr('Satuan','Unit')}}<select v-model="resource.unit"><option value="kg">kg</option><option value="piece">{{tr('Potong','Piece')}}</option></select></label><label>{{tr('Tarif','Rate')}} ({{data.currency}})<input v-model="resource.rate" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,4})?" required/></label><button class="service-primary" :disabled="busy">{{tr('Tambah','Add')}}</button></form><p v-else>{{tr('Layanan dan tarif dikelola pemilik bisnis di web.','The business owner manages services and rates on the web.')}}</p></section>
<form v-if="panel==='shift'" class="service-panel service-form" @submit.prevent="shift"><h2>{{data.shift?tr('Tutup kasir','Close register'):tr('Buka kasir','Open register')}}</h2><p>{{tr('Kas dan laporan shift khusus jenis usaha ini, terpisah dari kas POS barang.','This workflow has its own cash and shift report, separate from retail POS.')}}</p><label>{{data.shift?tr('Kas fisik akhir','Closing cash counted'):tr('Kas awal','Opening cash')}}<input v-model="shiftCash" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,4})?" required/></label><button class="service-primary" :disabled="busy">{{tr('Simpan','Save')}}</button><div v-if="receipt?.variance_atomic!==undefined" class="service-report"><h3>{{tr('Laporan tutup kas','Register closing report')}}</h3><p>{{tr('Awal','Opening')}}: {{money(receipt.opening_atomic)}}</p><p>{{tr('Penerimaan','Received')}}: {{money(receipt.received_atomic)}}</p><p>{{tr('Diharapkan','Expected')}}: {{money(receipt.expected_atomic)}}</p><p>{{tr('Dihitung','Counted')}}: {{money(receipt.counted_atomic)}}</p><p>{{tr('Selisih','Variance')}}: {{money(receipt.variance_atomic)}}</p><button type="button" @click="print">{{tr('Cetak / simpan PDF','Print / save PDF')}}</button></div></form>
<div v-if="selected" class="service-overlay"><section class="service-dialog" role="dialog" aria-modal="true" aria-labelledby="order-title"><button class="service-close" @click="selected=null">× {{tr('Tutup','Close')}}</button><h2 id="order-title">{{selected.customer_name}}</h2><p>{{selected.contact}} · {{selected.start_date}} → {{selected.end_date}}</p><p>{{tr('Nomor','Reference')}}: {{selected.id}}</p><p>{{statusNames[selected.status]?.[language==='en'?1:0]??selected.status}}</p><template v-for="invoice in invoices" :key="invoice.id"><div class="service-invoice"><h3>{{tr('Tagihan','Invoice')}} · {{invoice.period}}</h3><p>{{money(invoice.total_atomic)}} · {{tr('Dibayar','Paid')}} {{money(invoice.paid_atomic)}}</p><form v-if="Number(invoice.paid_atomic)<Number(invoice.total_atomic)" @submit.prevent="pay(invoice.id)"><label>{{tr('Pembayaran tunai','Cash payment')}}<input v-model="payment" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,4})?" required/></label><button :disabled="busy||!data.shift">{{tr('Catat pembayaran','Record payment')}}</button><small v-if="!data.shift">{{tr('Buka shift kasir terlebih dahulu.','Open the register shift first.')}}</small></form></div></template><form v-if="type==='boarding'&&['reserved','checked_in'].includes(selected.status)" @submit.prevent="command('invoice.create',{id:selected.id,version:Number(selected.version),period:billingPeriod})"><label>{{tr('Tanggal periode sewa berikutnya','Next rental period date')}}<input v-model="billingPeriod" type="date" required/></label><button :disabled="busy">{{tr('Buat tagihan periode','Create period invoice')}}</button></form><button v-if="nextState(selected.status)" class="service-primary" :disabled="busy" @click="command('order.transition',{id:selected.id,version:Number(selected.version),status:nextState(selected.status)})">{{tr('Lanjut ke','Continue to')}} {{statusNames[nextState(selected.status)]?.[language==='en'?1:0]}}</button><button v-if="['reserved','received'].includes(selected.status)" :disabled="busy" @click="command('order.transition',{id:selected.id,version:Number(selected.version),status:'cancelled'})">{{tr('Batalkan pesanan belum dibayar','Cancel unpaid order')}}</button><button @click="print">{{tr('Cetak / PDF','Print / PDF')}}</button></section></div></template></main></template>
<style scoped>
.service-workspace{font:16px/1.6 system-ui;color:#1B1B39}.service-head{display:flex;justify-content:space-between;gap:24px;align-items:center}.service-head h1{font-size:32px;margin:8px 0}.service-eyebrow{color:#3965FA;font-size:14px;font-weight:700}.service-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.service-kpis article,.service-panel{background:#FFFFFF;border:1px solid #E9EBFF;border-radius:20px;padding:24px;box-shadow:0 12px 30px #1B1B390A}.service-kpis strong{display:block;font-size:24px;margin-top:8px}.service-tabs{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.service-workspace button{font:600 16px system-ui;min-height:44px;padding:10px 16px;border:1px solid #99B7FC;background:#FFFFFF;color:#1B1B39;border-radius:10px;cursor:pointer}.service-workspace button[aria-current],.service-workspace .service-primary{background:#3965FA;color:#FFFFFF;border-color:#3965FA}.service-workspace button:disabled{opacity:.5;cursor:wait}.service-workspace label{display:grid;gap:8px;margin:16px 0}.service-workspace input,.service-workspace select{padding:12px;font:inherit;border:1px solid #99B7FC;border-radius:10px;background:#FFFFFF;color:#202020;width:100%;box-sizing:border-box}.service-form{max-width:760px}.service-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.service-table{overflow:auto}.service-table table{width:100%;border-collapse:collapse;text-align:left}.service-table th,.service-table td{padding:14px;border-bottom:1px solid #E9EBFF}.service-workspace small{display:block;font-size:14px}.service-badge{display:inline-block;padding:4px 10px;background:#E9EBFF;border-radius:8px;font-size:14px}.service-overlay{position:fixed;inset:0;background:#1B1B3980;z-index:90;display:grid;place-items:center;padding:20px}.service-dialog{background:#FFFFFF;max-width:740px;width:100%;max-height:85vh;overflow:auto;padding:28px;border-radius:24px;box-sizing:border-box}.service-close{float:right}.service-dialog button{margin:8px}.service-invoice{border-top:1px solid #E9EBFF;padding:12px 0}.service-error{padding:16px;border:1px solid #3965FA;border-radius:12px;background:#E9EBFF}.service-workspace :focus-visible{outline:3px solid #3965FA;outline-offset:3px}@media(max-width:720px){.service-head{display:block}.service-kpis{grid-template-columns:1fr}.service-grid{grid-template-columns:1fr}.service-panel{padding:18px}}@media print{.service-head,.service-kpis,.service-tabs,.service-panel,.service-close,.service-dialog button{display:none!important}.service-overlay{position:static;background:#FFFFFF;display:block;padding:0}.service-dialog{max-height:none;overflow:visible;width:100%;max-width:none;padding:0}.service-invoice form{display:none}.service-panel:has(.service-report){display:block!important}.service-panel>label,.service-panel>button{display:none}}
</style>
